<template><div class="demo-widget mission-widget" :style="widgetStyle(s)"><span class="widget-kicker">PROJECT RESPAWN · MISSION</span><b>{{ event.payload.title||s.title }}</b><p>{{ event.payload.current??s.current }} / {{ event.payload.target??s.target }} complete</p><div class="progress-track"><i :style="{width:`${percent}%`}"></i></div><footer><span>Reward: {{ event.payload.reward||s.reward }}</span><span>{{ s.timeRemaining }}</span></footer></div></template>
<script setup>import { computed } from 'vue'; import { widgetStyle,useWidgetEvents } from '../../widgetHelpers.js'; const props=defineProps({widget:{type:Object,required:true}}); const s=props.widget.settings; const event=useWidgetEvents(props.widget,{payload:{}}); const percent=computed(()=>Math.min(100,((event.value.payload.current??s.current)/(event.value.payload.target??s.target))*100))</script>
